import 'package:flutter/material.dart';
class AdvisorShell extends StatefulWidget{const AdvisorShell({super.key});@override State<AdvisorShell> createState()=>_AdvisorShellState();}class _AdvisorShellState extends State<AdvisorShell>{int index=0;static const titles=['الرئيسية','الطلبات','المواعيد','المحادثات','حسابي'];@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(titles[index])),body:Center(child:Text(titles[index],style:Theme.of(context).textTheme.headlineMedium)),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.inbox_outlined),label:'الطلبات'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),label:'المواعيد'),NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'المحادثات'),NavigationDestination(icon:Icon(Icons.person_outline),label:'حسابي')]));}}
